bool Codec<ContractCostParamEntry>::encode(const ContractCostParamEntry& v, Encoder& e) {
  return e.field("ext", v.ext) &&
      e.field("constTerm", v.constTerm) &&
      e.field("linearTerm", v.linearTerm);
}
bool Codec<ContractCostParamEntry>::decode(ContractCostParamEntry& v, Decoder& d) {
  Decoder::DepthGuard g(d);
  if (!g) return false;
  return d.field("ext", v.ext) &&
      d.field("constTerm", v.constTerm) &&
      d.field("linearTerm", v.linearTerm);
}
bool Codec<ContractCostParamEntry>::gen(ContractCostParamEntry& v, XdrRng& r, std::uint32_t depth) {
  if (!Codec<decltype(v.ext)>::gen(v.ext, r, depth)) return false;
  if (!Codec<decltype(v.constTerm)>::gen(v.constTerm, r, depth)) return false;
  if (!Codec<decltype(v.linearTerm)>::gen(v.linearTerm, r, depth)) return false;
  return true;
}

